/// Returns the largest power of two `z` such that `1 ≤ z ≤ n`.
fn largest_power_of_two_le(n: i8) -> i8 {
    // Precondition: n >= 1
    debug_assert!(n >= 1, "n must be at least 1");

    let mut z: i8 = 1;
    // Keep doubling z while it does not exceed n.
    // The check `z <= n / 2` ensures `z * 2` won't overflow and stays ≤ n.
    while z <= n / 2 {
        z *= 2;
    }
    z
}

/// Solves the problem:
/// - If n is odd, returns (n - 1) / 2.
/// - If n is even, finds z = largest_power_of_two_le(n), then returns (n - z) / 2.
pub fn solve(n: i8) -> i8 {
    // Precondition: n >= 1
    debug_assert!(n >= 1, "n must be at least 1");

    if n % 2 != 0 {
        // odd case
        (n - 1) / 2
    } else {
        // even case
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

